), desired AS (
    SELECT md5('grade1-practice:' || lesson || ':' || generator_key)::uuid AS id, *
    FROM catalog
)
INSERT INTO public.question_templates AS existing (
    id, name, classlevel, subject, semester, topic, lesson, question_type, generator_key, prompt_template, config, is_active
)
SELECT id, name, 'Lớp 1', subject, semester, topic, lesson, question_type, generator_key,
       '{question}', jsonb_build_object('lesson', lesson), true
FROM desired AS target
WHERE NOT EXISTS (
    SELECT 1 FROM public.question_templates AS other
    WHERE other.classlevel = 'Lớp 1'
      AND other.subject = target.subject AND other.semester = target.semester AND other.topic = target.topic
      AND coalesce(other.lesson, other.config->>'lesson') = target.lesson
      AND other.generator_key = target.generator_key AND other.id <> target.id
)
ON CONFLICT (id) DO UPDATE
SET name = excluded.name,
    question_type = excluded.question_type,
    prompt_template = excluded.prompt_template,
    config = excluded.config,
    updated_at = now()
WHERE existing.classlevel = 'Lớp 1'
  AND existing.subject = excluded.subject AND existing.semester = excluded.semester AND existing.topic = excluded.topic
  AND existing.lesson = excluded.lesson AND existing.generator_key = excluded.generator_key
  AND (existing.name, existing.question_type, existing.prompt_template, existing.config)
      IS DISTINCT FROM (excluded.name, excluded.question_type, excluded.prompt_template, excluded.config);
